(function(){
'use strict';
const A=PhantomAdapter,INDEX=A.freeze(window.PHANTOM_INDEX),main=document.getElementById('main');
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=s=>String(s).replaceAll('_',' ').toLowerCase().replace(/(^|\s)\S/g,x=>x.toUpperCase());
const short=s=>String(s).slice(0,8).toUpperCase();
const fmt=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:4});
const utc=(t,full=false)=>new Date(t*1000).toLocaleString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',...(full?{year:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'}:{hour:'2-digit',minute:'2-digit'}),hour12:false})+' UTC';
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',queue:'<path d="M8 5h13M8 12h13M8 19h13"/><circle cx="3" cy="5" r="1"/><circle cx="3" cy="12" r="1"/><circle cx="3" cy="19" r="1"/>',network:'<path d="m5 5 14 3-7 11L5 5m0 0 0 12 14-9"/><circle cx="5" cy="5" r="2"/><circle cx="19" cy="8" r="2"/><circle cx="12" cy="19" r="2"/><circle cx="5" cy="17" r="2"/>',research:'<path d="M4 4h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-3H4V4Zm9 3a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 3"/>',lineage:'<path d="M8 3h8l4 4v14H4V3h4m8 0v5h4M8 12h8M8 16h6"/>'};
const svg=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.research}</svg>`;
const nav=[['overview','Observatory'],['queue','Investigation queue'],['network','Network explorer'],['research','Research notes'],['lineage','Evidence lineage']];
document.getElementById('navigation').innerHTML='<div class="nav-label">WORKSPACE</div>'+nav.map(([k,v])=>`<a class="nav-item" data-nav="${k}" href="#${k}">${svg(k)}${v}</a>`).join('');
const cache=new Map(),pending=new Map();let routeSerial=0,playTimer=null,current=null,graph=null,lastFocus=null,filters={};
window.__phantomMetrics={};window.__phantomState={};
window.PHANTOM={register(alias,run){A.freeze(run);cache.set(alias,run);const p=pending.get(alias);if(p){pending.delete(alias);p.resolve(run);}}};
function load(alias){if(cache.has(alias))return Promise.resolve(cache.get(alias));if(pending.has(alias))return pending.get(alias).promise;const s=INDEX.sources.find(s=>s.alias===alias);if(!s)return Promise.reject(Error('Unknown authorized fixture.'));let resolve,reject;const promise=new Promise((r,j)=>{resolve=r;reject=j;});pending.set(alias,{promise,resolve,reject});const script=document.createElement('script');script.src='data/'+alias+'.js';script.onerror=()=>{pending.delete(alias);reject(Error('Unable to load frozen fixture '+alias+'. Keep the data folder beside index.html.'));};document.head.appendChild(script);return promise;}
function measure(name,fn){const t=performance.now(),result=fn();(window.__phantomMetrics[name]??=[]).push(performance.now()-t);return result;}
function announce(msg){document.getElementById('live').textContent=msg;}
function badge(text,cls=''){return `<span class="badge ${cls}">${e(text)}</span>`;}
function availability(v){return badge(A.AVAILABILITY[v]||v,v==='FIELD_AVAILABLE'?'available':v==='FIELD_NOT_AVAILABLE'||v==='REVIEW_REQUIRED'?'missing':'');}
function tierBadge(t){return badge(A.TIERS[t],'tier-'+t);}
function info(label,value){return `<dl class="label-value"><dt>${e(label)}</dt><dd>${value}</dd></dl>`;}
function note(c){return `<div class="ambiguity-note ${c.triage_tier==='D'?'warning-note':''}"><strong>${c.triage_tier==='D'?'OUT OF SUPPORT — DO NOT INTERPRET':c.triage_tier==='B'?'Event-only evidence cannot distinguish the competing causal explanations represented here.':'Causal attribution withheld · cause remains unresolved'}</strong><p>${e(c.visible_statement)}</p>${c.triage_tier==='D'?'<p>Raw reconstructed object retained for diagnostics. Statistical priority is withheld; graph geometry does not establish a supported parent interpretation.</p>':''}</div>`;}
function stat(label,value,sub=''){return `<div class="stat-box"><span>${e(label)}</span><b>${value}</b>${sub?`<small> ${e(sub)}</small>`:''}</div>`;}
function sourceName(alias){return INDEX.sources.find(s=>s.alias===alias)?.label||alias;}
function pageTitle(label){document.getElementById('page-label').textContent=label;document.title='PHANTOM · '+label;}
function setActive(key){document.querySelectorAll('[data-nav]').forEach(n=>{const selected=n.dataset.nav===key;n.classList.toggle('active',selected);if(selected)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});}
function go(hash){if(location.hash==='#'+hash)route();else location.hash=hash;}
function metric(label,value,note){return `<div class="metric"><div class="metric-label">${label}<span aria-hidden="true">↗</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function cohortCounts(){return Object.fromEntries(['A','B','C','D'].map(t=>[t,INDEX.candidates.filter(c=>c.triage_tier===t).length]));}
async function overview(token){
 const counts=cohortCounts(),total=INDEX.candidates.length,review=total-counts.D,sets=INDEX.groups.filter(g=>g.member_count>1),support={};INDEX.candidates.forEach(c=>support[c.support_status]=(support[c.support_status]||0)+1);
 pageTitle('Observatory');setActive('overview');
 main.innerHTML=`<section class="animate-in"><div class="nexus-hero"><div><img class="hero-umbrella" data-brand-lockup src="brand/assets/nexus-lockup-dark.svg" alt="NEXUS Research Initiative" width="190" height="44"><h1>PHANTOM</h1><p class="hero-positioning">Structure, <span class="gradient-text">made visible.</span></p><p class="hero-context">Coordination intelligence &amp; campaign investigation</p></div><div class="hero-cta"><span>RESEARCH SYSTEM / PHASE 10</span><button class="button-primary" data-action="queue">Explore investigation queue <span aria-hidden="true">↗</span></button></div></div><div class="hero-grid"><section class="card network-card" aria-label="Featured research network"><div class="card-header"><div><h2>The coordination field</h2><p>R-01 · Mixed structural review · retrospective snapshot</p></div>${badge('SYNTHETIC RESEARCH')}</div><div id="hero-network"><div class="loading-state" role="status">Loading frozen relationships…</div></div></section><aside class="card posture-card"><div class="posture-title">Research posture</div><div class="coverage-number">${(review/total*100).toFixed(1)}<span>%</span></div><p>Conditional-review coverage<br><strong>${review} of ${total}</strong> exported hypotheses</p><div class="coverage-track" aria-hidden="true"><i style="width:${review/total*100}%"></i></div><div class="posture-row"><span>Scientific outputs</span><b>Frozen · read only</b></div><div class="posture-row"><span>Causal resolution</span><b>Unresolved</b></div><div class="posture-row"><span>External context</span><b>0 / 10 categories</b></div><div class="posture-row"><span>Observation window</span><b>May 2022 · UTC</b></div><div class="posture-foot">${svg('lineage')}<span>Support concerns evidence applicability. It does not establish a cause.</span></div></aside></div><div class="metrics">${metric('Reviewable hypotheses',review,`${total} total · ${counts.D} out-of-support diagnostics`)}${metric('Ambiguity equivalence sets',sets.length,`${INDEX.groups.length} total classes · ${INDEX.groups.length-sets.length} singletons`)}${metric('Missing provenance',total,`Hypotheses with missing context · 10 / 10 fields each`)}${metric('Frozen research fixtures',INDEX.sources.length,'Controlled development demonstrations')}</div><div class="section-heading"><div><h2>Independent review destinations</h2><p>Queue layout is administrative. No cross-queue scientific or causal order.</p></div><button class="button-text" data-action="queue">Open queue →</button></div><div class="tiers-grid">${['A','B','C','D'].map(t=>`<button class="tier-card tier-${t}" data-action="tier" data-tier="${t}" aria-label="${e(A.TIERS[t])}, ${counts[t]} hypotheses"><div class="tier-top"><span>TIER ${t}</span><span aria-hidden="true">↗</span></div><div class="tier-name">${A.TIERS[t].split(' — ')[1]}</div><div class="tier-count">${counts[t]}</div><div class="tier-caption">${{A:'Conditional structure · cause unresolved',B:'Complete groups · no preferred member',C:'Bounded limitations remain visible',D:'Interpretation withheld · raw object retained'}[t]}</div></button>`).join('')}</div><div class="two-col"><section class="card card-pad"><div class="inline-heading"><h2>Current evidence scope</h2>${badge('RETROSPECTIVE')}</div><div class="scope-grid">${info('Dataset','Frozen Phase 9.2 synthetic development packets')}${info('Observation window','01 May – 29 May 2022 UTC · half-open')}${info('Accepted lineage','Phase 5.1 · pooling / consensus / fragment link')}${info('Population validation','No fresh real-population validation available')}</div><p class="scope-note section-spacer">This is a curated display of five complete runs, not the full benchmark. Counts describe exported hypotheses, not hidden original parents or a real population. The graph above is scoped to R-01.</p></section><section class="card card-pad"><h2>Support status distribution</h2><p class="understated">Separate from queue assignment</p><div class="support-bar" role="img" aria-label="${e(Object.entries(support).map(([k,v])=>title(k)+': '+v).join('; '))}">${Object.entries(support).map(([k,v],i)=>`<span style="width:${100*v/total}%;--seg-color:${['#959add','#88bfcb','#8c9bb5'][i]}"></span>`).join('')}</div><div class="support-legend">${Object.entries(support).map(([k,v],i)=>`<div><span><i style="--seg-color:${['#959add','#88bfcb','#8c9bb5'][i]}"></i>${title(k)}</span><strong>${v}</strong></div>`).join('')}<div><span>Unqualified Supported</span><strong>${support.SUPPORTED||0}</strong></div></div><p class="scope-note section-spacer">An available evidence packet is not a completed causal review.</p></section></div></section>`;
 const run=await load('R-01');if(token!==routeSerial)return;measure('graph_render',()=>graph=new PhantomGraph(document.getElementById('hero-network'),run.candidates,{compact:true}));announce('Observatory ready. '+review+' reviewable hypotheses. All causes unresolved.');
}
function field(id,label,content){return `<div class="field"><label for="${id}">${label}</label>${content}</div>`;}
function option(value,text){return `<option value="${e(value)}">${e(text)}</option>`;}
function queue(){
 pageTitle('Investigation queue');setActive('queue');
 main.innerHTML=`<section class="animate-in"><div class="page-heading"><div><div class="eyebrow">Evidence-led investigation</div><h1>Investigation queue</h1><p>Complete review classes. Every hypothesis retained. No preferred causal interpretation.</p></div>${badge(INDEX.candidates.length+' FROZEN HYPOTHESES')}</div><div class="filters">${field('query','Find a hypothesis or fixture','<input id="query" data-filter="query" type="search" placeholder="Search opaque ID or R-01…" autocomplete="off">')}${field('tier','Review destination',`<select id="tier" data-filter="tier">${option('','All four tiers')}${Object.entries(A.TIERS).map(([k,v])=>option(k,v)).join('')}</select>`)}${field('support','Support status',`<select id="support" data-filter="support">${option('','All support statuses')}${[...new Set(INDEX.candidates.map(c=>c.support_status))].map(v=>option(v,title(v))).join('')}</select>`)}${field('source','Research fixture',`<select id="source" data-filter="source">${option('','All five fixtures')}${INDEX.sources.map(s=>option(s.alias,s.alias+' · '+s.label)).join('')}</select>`)}</div><details class="advanced-filters"><summary>More evidence filters · time, size, coordination, ambiguity and provenance</summary><div class="advanced-grid">${field('from','Evidence intersects from (UTC)','<input id="from" data-filter="from" type="date" min="2022-05-01" max="2022-05-29">')}${field('to','Evidence intersects through (UTC)','<input id="to" data-filter="to" type="date" min="2022-05-01" max="2022-05-29">')}${field('size','Minimum campaign members','<input id="size" data-filter="size" type="number" min="0" placeholder="Any size">')}${field('targets','Minimum target count','<input id="targets" data-filter="targets" type="number" min="0" placeholder="Any count">')}${field('strength','Minimum constituent observed mean','<input id="strength" data-filter="strength" type="number" min="0" step="0.1" placeholder="Any coordination strength">')}${field('ambiguity','Causal ambiguity',`<select id="ambiguity" data-filter="ambiguity">${option('','All hypotheses')}${option('unresolved','Causally unresolved (all)')}${option('B','Tier B ambiguity review')}</select>`)}${field('provenance','Missing provenance',`<select id="provenance" data-filter="provenance">${option('','Any availability')}${option('missing','Missing independent provenance')}${option('complete','No missing provenance')}</select>`)}</div></details><div class="neutral-note">Filters find matching members and retain their <strong>entire equivalence group</strong>. Group count does not reduce inspection burden. Coordination strength is an observed constituent mean, not a calibrated probability.</div><div class="results-line"><span id="results-count" role="status"></span><button class="button-text" data-action="reset-filters">Reset filters</button></div><div id="queue-results"></div></section>`;
 document.querySelectorAll('[data-filter]').forEach(el=>{el.value=filters[el.dataset.filter]||'';el.addEventListener(el.tagName==='INPUT'?'input':'change',()=>{filters[el.dataset.filter]=el.value;renderQueue();});});renderQueue();
}
function renderQueue(){measure('queue_filter',()=>{
 const groups=A.groups(INDEX,filters);window.__phantomState.visibleGroups=groups;
 const direct=groups.reduce((n,g)=>n+g.matchCount,0),shown=groups.reduce((n,g)=>n+g.member_count,0);
 document.getElementById('results-count').innerHTML=`<strong>${shown}</strong> hypotheses shown · <strong>${direct}</strong> match filters · ${groups.filter(g=>!g.diagnostic).length} complete classes · ${groups.filter(g=>g.diagnostic).length} D diagnostics`;
 document.getElementById('queue-results').innerHTML=groups.length?groups.map(g=>groupTable(g)).join(''):`<div class="empty-state"><div class="eyebrow">No matching objects</div><h2>${filters.source==='R-05'?'No admitted campaign in this frozen run.':'No hypotheses match these filters.'}</h2><p>${filters.source==='R-05'?'No admitted campaign under the stated support and observation window. This does not clear accounts.':'Adjust the display filters to inspect the retained research evidence.'}</p><button data-action="reset-filters">Reset filters</button></div>`;
 announce(shown+' hypotheses shown in complete classes and diagnostic objects.');
 });}
function groupTable(g){return `<section class="equivalence-group tier-${g.triage_tier}" data-group-id="${e(g.equivalence_set_id||'diagnostic')}" data-run-id="${e(g.run_id)}"><div class="group-heading"><div><h3>${e(A.TIERS[g.triage_tier])}</h3><p>${e(g.source)} · ${e(sourceName(g.source))} · ${g.diagnostic?'Unranked diagnostic object':g.member_count+' member'+(g.member_count!==1?'s':'')+' · '+(g.member_count>1?'ambiguity equivalence set':'singleton class')}</p></div>${!g.diagnostic?`<button class="row-open" data-action="group" data-source="${g.source}" data-id="${g.equivalence_set_id}">Inspect complete class ↗</button>`:badge('NO SCIENTIFIC PRIORITY','tier-D')}</div>${!g.diagnostic?`<div class="group-meta"><span>Equal scientific priority; display order has no scientific meaning.</span><code>scientific_priority_equal = true</code><span>All ${g.member_count} members retained · ${g.matchCount} match filters</span></div>`:'<div class="group-meta">Required interpretation conditions fail. Evidence preserved for diagnostics; no equivalence assertion.</div>'}<div class="table-wrap"><table class="queue-table"><caption class="sr-only">All members of ${e(g.source)} ${e(g.equivalence_set_id||'diagnostic')}. Order is non-semantic.</caption><thead><tr><th scope="col">Campaign hypothesis</th><th scope="col">Structure</th><th scope="col">Support status</th><th scope="col">Evidence interval</th><th scope="col">Inspect</th></tr></thead><tbody>${g.members.map(c=>`<tr data-candidate="${c.campaign_id}" class="hypothesis-row"><td><span class="id-cell mono">${short(c.campaign_id)}</span><span class="cell-secondary">Cause unresolved · ${c.fragment_count} fragment${c.fragment_count>1?'s':''}</span></td><td>${c.member_count} users · ${c.target_count} targets<span class="cell-secondary">${c.missing_provenance_count} missing provenance fields</span></td><td>${badge(title(c.support_status),c.triage_tier==='D'?'tier-D':'caution')}<span class="cell-secondary">${c.triage_tier==='D'?'Interpretation withheld':'Conditional evidence only'}</span></td><td>${utc(c.evidence_period[0])}<span class="cell-secondary">to ${utc(c.evidence_period[1])} · end exclusive</span></td><td><button class="row-open" data-action="case" data-source="${c.source}" data-id="${c.campaign_id}" aria-label="Inspect hypothesis ${short(c.campaign_id)}">Open ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;}
async function groupPage(source,id,token){const run=await load(source);if(token!==routeSerial)return;const g=run.ambiguity_equivalence_sets.find(x=>x.equivalence_set_id===id);if(!g)throw Error('Class not present in this frozen run.');const members=g.member_candidate_ids.map(id=>run.candidates.find(c=>c.campaign_id===id));pageTitle('Equivalence workspace');setActive('queue');current={run,source,group:g};window.__phantomState.group=g;
 main.innerHTML=`<section class="animate-in"><button class="back-link" data-action="queue">← Investigation queue</button><div class="page-heading"><div><div class="eyebrow">${e(source)} · complete review class</div><h1>${members.length>1?'Equal priority. <span class="gradient-text">Open cause.</span>':'Singleton structural review'}</h1><p>${members.length} ${members.length===1?'hypothesis':'hypotheses'} · ${e(A.TIERS[g.triage_tier])}</p></div><button class="button-primary" data-action="export-group">Export complete class ↓</button></div><div class="group-summary"><h2>SCIENTIFICALLY EQUAL PRIORITY</h2><p>Display order has no scientific meaning. Causal resolution unavailable from current event data.</p><p>${e(g.scientific_equivalence_reason)}</p><div class="button-row">${badge('scientific_priority_equal = true','tier-B')}${badge('presentation_order_semantic = false')}${badge('causal_preference_permitted = false')}</div><p class="understated">${g.member_count} candidate inspections are needed for full hypothesis coverage. No member is preselected. A singleton does not imply competing candidates or a uniquely known cause.</p></div><div class="ambiguity-note"><strong>Event-only evidence cannot distinguish the competing causal explanations represented here.</strong><p>These events admit multiple causal explanations. PHANTOM does not determine manipulative intent or verify innocence.</p></div><div class="member-grid">${members.map(c=>`<article class="member-card" data-candidate="${c.campaign_id}"><div class="inline-heading"><h3>${short(c.campaign_id)}</h3>${tierBadge(c.triage_tier)}</div><p>Campaign hypothesis · ${title(c.support_status)}</p><div class="member-stats"><span>${c.member_users.length} users</span><span>${c.target_tracks.length} targets</span><span>${c.linked_fragments.length} fragment${c.linked_fragments.length>1?'s':''}</span></div><p>${utc(c.evidence_period[0])} → ${utc(c.evidence_period[1])}<br>End exclusive · independent context unavailable</p>${badge('EQUAL SCIENTIFIC PRIORITY','tier-B')}<button class="row-open" data-action="case" data-source="${source}" data-id="${c.campaign_id}">Inspect hypothesis ${short(c.campaign_id)} ↗</button></article>`).join('')}</div><div class="section-heading"><h2>Shared representation & retained context</h2></div><details class="accordion"><summary>Exact class record ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>Equality is specific to the frozen five-dimensional review key and structural routing signature. Finer event statistics remain different and are retained in this record.</p><pre class="json-box">${e(JSON.stringify(g,null,2))}</pre></div></details></section>`;announce('Complete class opened. '+members.length+' members, equal priority; none preselected.');}
async function networkPage(source='R-01',selected='',token){const run=await load(source);if(token!==routeSerial)return;pageTitle('Network explorer');setActive('network');const c=run.candidates.find(c=>c.campaign_id===selected);current={source,run,candidate:c};main.innerHTML=`<section class="animate-in"><div class="page-heading"><div><div class="eyebrow">Retrospective structural evidence</div><h1>The network <span class="gradient-text">workspace.</span></h1><p>Observed relationships, reconstructed hypotheses and unsupported links remain distinct.</p></div>${badge('GEOMETRY IS NON-SEMANTIC')}</div><div class="filters">${field('network-source','Research fixture',`<select id="network-source">${INDEX.sources.map(s=>option(s.alias,s.alias+' · '+s.label)).join('')}</select>`)}${field('network-case','Isolate a hypothesis',`<select id="network-case">${option('','All hypotheses · none preferred')}${run.candidates.map(c=>option(c.campaign_id,short(c.campaign_id)+' · Tier '+c.triage_tier)).join('')}</select>`)}</div><div class="neutral-note">${c?e(A.TIERS[c.triage_tier])+' · '+e(title(c.support_status)):'All hypotheses receive the same node styling. No causal preference is represented.'} · This network shows one research fixture at a time. Distinct runs are not joined.</div>${c?note(c):'<div class="ambiguity-note"><strong>Event-only evidence cannot distinguish the competing causal explanations represented here.</strong><p>These events admit multiple causal explanations. PHANTOM does not determine manipulative intent or verify innocence.</p></div>'}<section class="card network-card" id="explorer-graph"></section>${c?`<div class="button-row section-spacer"><button class="button-primary" data-action="case" data-source="${source}" data-id="${c.campaign_id}">Open complete evidence workspace ↗</button>${tierBadge(c.triage_tier)}</div>`:''}<div class="neutral-note">Circles identify users; diamonds identify target tracks. Solid relations show measured temporal observations; dashed relations show catalog-only or cross-fragment context. Edge intensity is descriptive coincidence strength. Pair relations are not independently significant tests. Spatial proximity does not establish an organizer or common cause.</div></section>`;document.getElementById('network-source').value=source;document.getElementById('network-case').value=selected;document.getElementById('network-source').onchange=ev=>go('network/'+ev.target.value);document.getElementById('network-case').onchange=ev=>go('network/'+source+'/'+ev.target.value);if(run.candidates.length)measure('graph_render',()=>graph=new PhantomGraph(document.getElementById('explorer-graph'),c?[c]:run.candidates));else document.getElementById('explorer-graph').innerHTML='<div class="empty-state"><h2>No admitted campaign</h2><p>This run has no candidate graph. It does not clear accounts.</p></div>';}
const tabs=[['structure','Structure'],['timeline','Timeline'],['evidence','Evidence packet'],['support','Support checks'],['alternatives','Causal alternatives'],['provenance','Missing provenance']];
async function detail(source,id,tab='structure',token){
 const t=performance.now(),run=await load(source);if(token!==routeSerial)return;const c=run.candidates.find(c=>c.campaign_id===id);if(!c)throw Error('Hypothesis not present in this source run.');if(!tabs.some(x=>x[0]===tab))tab='structure';current={source,run,candidate:c,tab};window.__phantomState.candidate=c;pageTitle('Hypothesis '+short(id));setActive('queue');
 const group=run.ambiguity_equivalence_sets.find(g=>g.equivalence_set_id===c.equivalence_set_id);
 main.innerHTML=`<section class="animate-in"><button class="back-link" data-action="${group?'group':'queue'}" data-source="${source}" data-id="${group?.equivalence_set_id||''}">← ${group?'Complete class · '+group.member_count+' member'+(group.member_count>1?'s':''):'Investigation queue'}</button><div class="page-heading detail-heading"><div><div class="eyebrow">${e(source)} · campaign hypothesis</div><h1>Hypothesis <span class="gradient-text">${short(c.campaign_id)}</span></h1><div class="detail-id">Frozen evidence · ${e(sourceName(source))}</div><div class="detail-badges">${tierBadge(c.triage_tier)}${badge(title(c.support_status),'caution')}${badge('CAUSALLY UNRESOLVED')}</div></div><div class="button-row"><button class="icon-button" data-action="academic-report">Export academic brief ↓</button><button class="icon-button" data-action="packet">Full source packet</button><a class="artifact-link" href="data/${source}.json" download="PHANTOM_${source}_Frozen_Run.json">Download complete run ↓</a></div></div>${note(c)}${group?`<div class="neutral-note">Equal scientific priority; display order has no scientific meaning. <strong>${group.member_count} member${group.member_count>1?'s':''}</strong> in this run-scoped class. ${group.member_count>1?'This hypothesis was opened by the reviewer; no default or preferred member exists.':'Singleton class; this does not establish a uniquely known cause.'} <code>scientific_priority_equal = true</code> · <code>presentation_order_semantic = false</code></div>`:''}<nav class="tabs" aria-label="Evidence views">${tabs.map(([k,label])=>`<button class="${tab===k?'active':''}" data-action="tab" data-tab="${k}" ${tab===k?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="detail-grid"><div id="detail-view" class="detail-content"></div><aside class="detail-aside"><section class="card"><h3>Recommended analyst action</h3><div class="action-label" data-action-value="${e(A.action(c))}">${e(A.action(c))}</div><p>Presentation mapping approved for Phase 10. The source action remains immutable.</p>${info('Frozen source action',e(c.recommended_action))}${info('Action rationale',e(c.action_rationale))}</section><section class="card"><h3>Evidence boundaries</h3>${info('Evidence start',e(utc(c.evidence_period[0],true)))}${info('Evidence end · exclusive',e(utc(c.evidence_period[1],true)))}${info('Evidence cutoff',e(utc(c.evidence_cutoff,true)))}${info('Observation scope','01–29 May 2022 UTC · fixed historical window')}${info('Conditional analysis','511 draws · add-one resolution 1/512')}${info('Independent context',availability('FIELD_NOT_AVAILABLE'))}${info('Causal review',availability(c.context_review.availability))}${info('Merged statistic',availability(c.merged_campaign_statistic.availability))}</section><section class="card"><h3>Immutable review history</h3>${info('Current state',e(c.workflow.state))}<p>${c.workflow.history.length?'Frozen source history is available below.':'No reviewer transition has been recorded. Displaying this packet does not complete a review.'}</p><button class="button-text" data-action="workflow">Inspect state & history →</button></section></aside></div></section>`;
 const view=document.getElementById('detail-view');
 if(tab==='structure'){view.innerHTML=structure(c);measure('graph_render',()=>graph=new PhantomGraph(document.getElementById('case-graph'),[c]));}
 if(tab==='timeline'){measure('timeline_render',()=>{view.innerHTML=timeline(c);bindTimeline(c);});}
 if(tab==='evidence')view.innerHTML=evidence(c);
 if(tab==='support')view.innerHTML=support(c);
 if(tab==='alternatives')view.innerHTML=alternatives(c);
 if(tab==='provenance')view.innerHTML=provenance(c);
 (window.__phantomMetrics.detail_load??=[]).push(performance.now()-t);announce('Hypothesis '+short(c.campaign_id)+', '+A.TIERS[c.triage_tier]+'. '+tabs.find(x=>x[0]===tab)[1]+' view. Cause unresolved.');
}
function structure(c){return `<section class="card network-card"><div class="card-header"><h2>Relational structure</h2>${badge(c.triage_tier==='D'?'RAW DIAGNOSTIC':'CONDITIONAL HYPOTHESIS',c.triage_tier==='D'?'tier-D':'')}</div><div id="case-graph"></div></section><div class="stat-row">${stat('Reconstructed members',c.member_users.length)}${stat('Catalog targets',c.target_tracks.length)}${stat('Original fragments',c.linked_fragments.length)}${stat('Supporting windows',c.temporal_evidence.supporting_slots)}</div><section class="card card-pad"><h2>Constituent evidence</h2><p class="understated">${c.triage_tier==='D'?'Frozen numerical record for diagnostics only. Statistical interpretation and scientific priority are withheld.':'Conditional null-relative evidence. These are constituent statistics, never a merged significance or causal probability.'}</p><div class="table-wrap"><table class="numeric-table"><caption class="sr-only">Exact frozen constituent statistics</caption><thead><tr><th scope="col">Constituent</th><th scope="col">Observed mean</th><th scope="col">Null median</th><th scope="col">Null scale</th><th scope="col">Familywise MC p</th></tr></thead><tbody>${c.coordination_strength.map((x,i)=>`<tr><td>${i+1}</td><td title="${x.observed}">${e(x.observed)}</td><td title="${x.null_median}">${e(x.null_median)}</td><td>${e(x.null_scale)}</td><td>${e(x.familywise_p)}</td></tr>`).join('')}</tbody></table></div><p class="scope-note">511 fixed draws · 1/512 resolution · no tail extrapolation. Pair edges are descriptive, not independently significant tests. A zero-scale signed 1e12 sentinel is never an ordinary normal-tail score.</p><details class="accordion section-spacer"><summary>Original normalization & provenance ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><pre class="json-box">${e(JSON.stringify(c.coordination_strength,null,2))}</pre></div></details></section><div class="section-heading"><h2>Evidence & counterevidence</h2></div><div class="dense-grid"><section class="evidence-card"><h3>Observed relational evidence</h3>${availability('FIELD_AVAILABLE')}<p>${c.graph_evidence.complete_pair_denominator} complete pairs enter the reported pooled denominator. Frozen temporal density: ${e(c.graph_evidence.temporal_density)}. Catalog density: ${e(c.graph_evidence.catalog_density)}.</p><p>Fixed minimum 60/300 pair evidence. Catalog targets are hypotheses; inspect their temporal status individually.</p></section><section class="evidence-card"><h3>Counterevidence & limits</h3>${availability('FIELD_AVAILABLE')}<ul class="fact-list">${c.counterevidence.map(x=>`<li>${e(x.statement||title(x.type)+(x.track_ids?' · '+x.track_ids.length+' track(s)':' remains recorded'))}</li>`).join('')}</ul></section></div><div class="section-heading"><h2>Members, targets & fragments</h2></div><details class="accordion"><summary>All reconstructed members · ${c.member_users.length} ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>Opaque source identifiers. Membership is a reconstructed hypothesis.</p><pre class="json-box" data-members>${e(JSON.stringify(c.member_users,null,2))}</pre></div></details><details class="accordion"><summary>All target tracks · ${c.target_tracks.length} ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><div class="table-wrap"><table class="numeric-table"><caption class="sr-only">Catalog and temporal target support</caption><thead><tr><th scope="col">Track</th><th scope="col">Provenance</th><th scope="col">Supporting members</th><th scope="col">Temporal support</th></tr></thead><tbody>${c.target_tracks.map(t=>`<tr><td>${e(t.track_id)}</td><td>${e(t.provenance)}</td><td>${t.supporting_member_count}</td><td>${e(t.temporal_support)}</td></tr>`).join('')}</tbody></table></div></div></details><details class="accordion"><summary>Original fragments & links · ${c.linked_fragments.length} / ${c.fragment_links.length} ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>All fragment members, targets, intervals and original link measurements are retained. Association does not establish one organizer or unique parent.</p><pre class="json-box">${e(JSON.stringify({linked_fragments:c.linked_fragments,fragment_links:c.fragment_links},null,2))}</pre></div></details><details class="accordion"><summary>Complete pair network & strongest reported relations ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>All pairs are retained, including zero coincidence and cross-fragment descriptive relations. Source-reported strongest relations are a descriptive subset; equal weights may have other equally strong relations.</p><pre class="json-box">${e(JSON.stringify(c.graph_evidence,null,2))}</pre></div></details>`;}
function timeline(c){
 const rows=c.temporal_evidence.timeline,slots=[...new Set(rows.map(r=>r.slot))].sort((a,b)=>a-b),bySlot=slots.map(slot=>{const r=rows.filter(r=>r.slot===slot);return {slot,start:Math.min(...r.map(x=>x.timestamp)),end:Math.max(...r.map(x=>x.timestamp)),count:r.length};});
 const start=c.evidence_period[0],end=c.evidence_period[1],x=t=>80+700*(t-start)/(end-start),max=Math.max(1,...bySlot.map(s=>s.count));
 const H=180+c.linked_fragments.length*32;
 return `<section class="card timeline-card"><div class="inline-heading"><div><h2>Evidence across time</h2><p class="understated">Retrospective selected observations · no activity inferred in gaps</p></div>${badge('UTC')}</div><svg class="timeline-svg" viewBox="0 0 820 ${H}" role="img" aria-label="Timeline of ${slots.length} recurring observed windows and ${c.linked_fragments.length} fragment periods. Bars count recorded selected observations, not continuous monitoring."><line class="axis" x1="80" y1="130" x2="780" y2="130"/>${bySlot.map(s=>`<rect class="window" x="${x(s.start)}" y="${125-75*s.count/max}" width="${Math.max(3,x(s.end)-x(s.start))}" height="${75*s.count/max}" rx="1"><title>Slot ${s.slot}: ${s.count} observations, ${utc(s.start,true)} to ${utc(s.end,true)}</title></rect>`).join('')}<text x="80" y="24">Recorded selected observations</text><text class="axis-label" x="80" y="150">${e(utc(start))}</text><text class="axis-label" x="780" y="150" text-anchor="end">${e(utc(end))}</text>${c.linked_fragments.map((f,i)=>`<text class="axis-label" x="6" y="${182+i*32}">Fragment ${i+1}</text><rect class="fragment-bar" x="${x(f.evidence_period[0])}" y="${171+i*32}" width="${Math.max(1,x(f.evidence_period[1])-x(f.evidence_period[0]))}" height="14" rx="3"><title>${e(f.fragment_id)} · ${utc(f.evidence_period[0],true)} to ${utc(f.evidence_period[1],true)}, exclusive end</title></rect>`).join('')}<line id="timeline-cursor" class="cursor-line" x1="80" y1="35" x2="80" y2="${H-8}" visibility="hidden"/></svg><div class="timeline-controls"><button class="icon-button" id="play-timeline" aria-pressed="false">Play observations ▷</button><label for="timeline-range">Window</label><input id="timeline-range" type="range" min="0" max="${Math.max(0,slots.length-1)}" value="0" step="1"><button class="icon-button" id="full-interval">Full interval</button></div><div class="timeline-time" id="timeline-time" role="status">Full observed interval · ${slots.length} windows</div><div class="neutral-note">Playback highlights recorded user–track events at each source slot. Aggregate pair evidence is not recomputed. Fragment bars span evidence intervals; they do not assert continuous activity.</div></section><section class="card network-card section-spacer" id="timeline-graph"></section><div class="dense-grid section-spacer"><section class="evidence-card"><h3>Finite observation</h3><p>Only recorded observations before ${e(utc(c.evidence_cutoff,true))} enter this packet. Absent users, targets or activity cannot be recovered or ruled out. Evidence end is exclusive.</p></section><section class="evidence-card"><h3>Candidate evolution</h3>${availability('FIELD_NOT_AVAILABLE')}<p>The frozen packet contains a retrospective hypothesis and fragment periods. It does not supply a series of changing candidate versions.</p></section></div><details class="accordion section-spacer"><summary>Every recorded window & observation ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>Complete source timeline, including user, target, timestamp, slot and consensus-presence status.</p><pre class="json-box">${e(JSON.stringify(c.temporal_evidence,null,2))}</pre></div></details>`;
}
function bindTimeline(c){
 graph=measure('graph_render',()=>new PhantomGraph(document.getElementById('timeline-graph'),[c]));const rows=c.temporal_evidence.timeline,slots=[...new Set(rows.map(r=>r.slot))].sort((a,b)=>a-b),slider=document.getElementById('timeline-range'),button=document.getElementById('play-timeline');
 function show(){const slot=slots[+slider.value],events=rows.filter(x=>x.slot===slot);const t=Math.min(...events.map(x=>x.timestamp));const x=80+700*(t-c.evidence_period[0])/(c.evidence_period[1]-c.evidence_period[0]);const line=document.getElementById('timeline-cursor');line.setAttribute('visibility','visible');line.setAttribute('x1',x);line.setAttribute('x2',x);document.getElementById('timeline-time').textContent='Slot '+slot+' · '+utc(t,true)+' · '+events.length+' selected observations';slider.setAttribute('aria-valuetext','Slot '+slot+', '+utc(t,true));graph.showSlot(slot);}
 function stop(){clearInterval(playTimer);playTimer=null;button.textContent='Play observations ▷';button.setAttribute('aria-pressed','false');}
 slider.oninput=()=>{stop();show();};button.onclick=()=>{if(playTimer){stop();return;}if(+slider.value>=slots.length-1)slider.value=0;show();button.textContent='Pause playback Ⅱ';button.setAttribute('aria-pressed','true');playTimer=setInterval(()=>{slider.value=+slider.value+1;show();if(+slider.value>=slots.length-1)stop();},650);};document.getElementById('full-interval').onclick=()=>{stop();graph.showSlot(null);document.getElementById('timeline-cursor').setAttribute('visibility','hidden');document.getElementById('timeline-time').textContent='Full observed interval · '+slots.length+' windows';};
}
const sectionNames={overview:'Campaign overview',timeline:'Timeline',member_network:'Full member network',targets:'Target tracks',strongest_graph_relations:'Strongest graph relations',strongest_temporal_relations:'Strongest temporal relations',fragments:'Fragments and original links',null_relative_statistics:'Statistical / null evidence',population_context:'Population and contextual evidence',counterevidence:'Counterevidence',common_cause:'Common-cause alternatives',routine_context:'Routine context',uncertainty:'Uncertainty',support_assessment:'Support assessment',investigation_priority:'Investigation priority',independent_context:'Independent provenance',audit_trail:'Audit trail'};
function evidence(c){return `<div class="section-heading" style="margin-top:0"><div><h2>The full evidence packet</h2><p>All 17 sections, exact source content, availability and references.</p></div><button class="icon-button" data-action="packet">Inspect full JSON</button></div><div class="stat-row">${stat('Schema sections',Object.keys(c.sections).length,'/ 17')}${stat('Scientific availability',Math.round(c.packet_completeness.actual_usable_scientific_fraction*100)+'%')}${stat('Independent context','0','/ 10')}${stat('Causal review','Pending')}</div><div class="neutral-note">Schema completeness, sourced scientific evidence, external-context availability and completed causal review are different quantities. Required review is still <strong>REVIEW REQUIRED</strong>. No merged campaign statistic exists.</div>${Object.entries(sectionNames).map(([k,label])=>{const s=c.sections[k];return `<details class="accordion" data-section="${k}"><summary>${label} ${availability(s.availability)}</summary><div class="accordion-body"><p><strong>Evidence references:</strong> ${s.evidence_refs.map(e).join(' · ')||'None'}</p><p><strong>Section limitations:</strong> ${s.limitations.length?s.limitations.map(e).join(' · '):'No additional section-specific limitations; packet-wide limits still apply.'}</p>${s.availability==='FIELD_NOT_AVAILABLE'?'<p>NOT AVAILABLE IN CURRENT DATA. No independent values have been supplied.</p>':''}<pre class="json-box">${e(JSON.stringify(s.content,null,2))}</pre></div></details>`;}).join('')}<details class="accordion"><summary>Finite-draw / null limitations ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><pre class="json-box">${e(JSON.stringify(c.finite_draw_limitations,null,2))}</pre>${c.uncertainty.map(u=>`<p><strong>${e(u.type)}:</strong> ${e(u.statement)}</p>`).join('')}</div></details><details class="accordion"><summary>Unsupported interpretations ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><ul class="fact-list">${c.known_unsupported_interpretations.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div></details><details class="accordion"><summary>Reference index & exact packet digest ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><p>authorized:// references are original symbolic lineage locators, not network links. This demo includes the complete frozen packets; upstream arrays and replay artifacts are not bundled or fetched.</p><pre class="json-box">${e(JSON.stringify({evidence_packet_ref:c.evidence_packet_ref,core_object_ref:c.core_object_ref,evidence_refs:c.evidence_refs},null,2))}</pre></div></details>`;}
const checkNames={S1:'Integrity & observation cutoff',S2:'Canonical identity',S3:'Selection provenance',S4:'Null-invariant candidate family',S5:'Null provenance & replay',S6:'Reconstruction & constituents',S7:'Restricted interpretation',S8:'Evidence disclosure'};
function support(c){return `<div class="section-heading" style="margin-top:0"><div><h2>Eight explicit support checks</h2><p>Support is applicability of evidence, not causal attribution.</p></div>${badge(title(c.support_assessment.structural_support),c.triage_tier==='D'?'tier-D':'available')}</div><div class="neutral-note">A mandatory FAIL, UNKNOWN or required NOT APPLICABLE cannot be treated as PASS. A PASS for restricted structural interpretation does not complete the independent causal review. The frozen checks below are read only.</div><div class="dense-grid">${c.support_assessment.checks.map(s=>`<section class="support-check" data-check="${s.check_id}" data-result="${s.result}"><div class="check-number">${s.check_id}</div><div><div class="check-top"><strong>${checkNames[s.check_id]}</strong>${badge((s.result==='PASS'?'✓ ':s.result==='FAIL'?'× ':s.result==='UNKNOWN'?'? ':'— ')+s.result,'check-'+s.result)}</div><p>${e(s.reason)}</p><div class="check-meta"><span>${s.mandatory_for_statistical_interpretation?'Mandatory':'Optional'}</span><span>${s.human_or_provenance_review_required?'Review / provenance required':'No additional check-specific review requirement'}</span></div><p>Source: <code>${s.evidence_source.map(e).join(' · ')}</code><br>Origin: ${e(s.assessor_origin)} · Revision ${s.revision} · ${e(s.recorded_at)}</p></div></section>`).join('')}</div><section class="card card-pad section-spacer"><h3>Retained support reasons</h3><ul class="fact-list">${c.support_assessment.reason_codes.map(x=>`<li><code>${e(x)}</code></li>`).join('')}</ul><h3>Overlap / bridge interpretation</h3><p class="understated">${e(c.overlap_bridge_risk.parent_interpretation)} · ${e(c.overlap_bridge_risk.shifted_actor_overlap)}</p><pre class="json-box">${e(JSON.stringify(c.overlap_bridge_risk,null,2))}</pre></section><details class="accordion section-spacer"><summary>Original support history ${availability('FIELD_AVAILABLE')}</summary><div class="accordion-body"><pre class="json-box">${e(JSON.stringify(c.support_assessment.history,null,2))}</pre></div></details>`;}
const alternativeNames={COORDINATED_MANIPULATION:'Coordinated manipulation',RELEASE_POPULARITY_SHOCK:'Release / popularity response',FANDOM_COMMUNITY_RESPONSE:'Community / fandom response',RECURRING_ROUTINE:'Recurring routine',EXTERNAL_EVENT:'Shared external stimulus',UNKNOWN_COMMON_CAUSE:'Unknown common cause'};
function alternatives(c){return `<div class="section-heading" style="margin-top:0"><div><h2>Six explanations remain open</h2><p>Nonexclusive alternatives. No probabilities, causal winner or preferred candidate.</p></div>${badge('ATTRIBUTION WITHHELD','tier-B')}</div><div class="dense-grid">${c.alternative_hypotheses.map(a=>`<section class="evidence-card"><h3>${e(alternativeNames[a.type]||title(a.type))}</h3>${badge(a.assessment,'tier-B')}<p>${e(a.rationale)}</p><p class="callout-meta">Origin: ${e(a.assessor_origin)}<br>Supporting references: ${a.supporting_evidence_refs.map(e).join(', ')}<br>Counterevidence references: ${a.counterevidence_refs.map(e).join(', ')}</p><details class="accordion section-spacer"><summary>Missing evidence</summary><div class="accordion-body"><ul class="fact-list">${a.missing_evidence.map(x=>`<li>${e(title(x))}</li>`).join('')}</ul></div></details></section>`).join('')}</div><section class="card card-pad section-spacer"><h3>Observed context does not identify a cause</h3><p class="scope-note">${e(c.common_cause_risk.rationale)}</p><p class="scope-note">${e(c.routine_structure_risk.rationale)}</p><p class="scope-note">A missing common-cause indicator is not evidence that a common cause is unlikely. Shared external stimulus and intentional organization can coexist.</p></section>`;}
function provenance(c){return `<div class="section-heading" style="margin-top:0"><div><h2>External evidence that could help resolve this case</h2><p>Ten source-defined causal questions. No values fabricated or inferred.</p></div></div><div class="neutral-note">All categories are <strong>NOT AVAILABLE IN CURRENT DATA</strong>. This read-only dashboard does not collect provenance. Future independently sourced evidence would require a separate authorized protocol; availability alone would not establish cause.</div><div class="dense-grid">${c.provenance_requirements_still_missing.map(p=>`<section class="provenance-card" data-provenance="${p.field}"><h3>${e(title(p.field))}</h3><p>${e(p.question)}</p>${availability(p.availability)}<p class="callout-meta">Value: null · ${e(p.reason)}</p></section>`).join('')}</div>`;}
function research(){pageTitle('Research notes');setActive('research');main.innerHTML=`<section class="animate-in"><div class="page-heading"><div><div class="eyebrow">Scientific context · concise research brief</div><h1>A powerful lens.<br><span class="gradient-text">A deliberate boundary.</span></h1><p>PHANTOM reconstructs unusual coordinated structures within its declared support. It leaves causal interpretation open.</p></div>${badge('RESEARCH DEMONSTRATION')}</div><div class="feature-quote"><div class="eyebrow">NEXUS Research Initiative / PHANTOM</div><p>PHANTOM is a research system under the NEXUS Research Initiative identity. This name does not assert institutional, corporate or university affiliation.</p><div class="eyebrow">The identifiability boundary</div><p>Identical observed events can have different hidden causes. More elaborate event-only modeling cannot recover information that is absent from the observations.</p><span class="understated">Literal causal twins establish this limit for matched arrays. Equal review-priority keys alone do not prove identical event histories.</span></div><div class="research-grid"><article class="card research-card"><div class="eyebrow">01 / External transfer</div><h2>Evidence belongs to its lineage.</h2><p>The earlier external study tested a different frozen population detector on controlled planted coordination in ListenBrainz histories. It does not externally validate the current campaign reconstruction or investigation layer.</p><div class="source-cite">Source: Phase 7.2 Investigation Reframing Report · historical Phase 4.12 summary</div></article><article class="card research-card"><div class="eyebrow">02 / Campaign reconstruction</div><h2>Structure can be recovered.</h2><p>Phase 5.1 retained conditional graph pooling, fixed 60/300-second consensus and fragment association. Its one-pass internal holdout reported member and target F1 of 0.9167 on that bounded panel. That holdout is consumed historical evidence.</p><div class="source-cite">Source: Phase 5.1 Internal Holdout Report · not fresh validation</div></article><article class="card research-card"><div class="eyebrow">03 / Robustness</div><h2>Passing settings have limits.</h2><p>Duplicate stability and fixed reporting-bin invariance were preserved. Sampled observation-loss and jitter cases showed bounded resilience, while weaker signal, severe loss, shifted overlap and catalog bridges exposed failures. These are not universal operating thresholds.</p><div class="source-cite">Sources: Phase 7.2 Reframing Report; Phase 8 Robustness and Overlap reports</div></article><article class="card research-card"><div class="eyebrow">04 / Common cause</div><h2>Coordination does not identify intent.</h2><p>Release, popularity and external-event response fixtures can produce strong coordinated structure. Event-only evidence cannot select an exclusive cause. Six nonexclusive alternatives and all missing-provenance questions remain visible for every hypothesis.</p><div class="source-cite">Sources: Phase 7.2 Causal Identifiability Note; Phase 8 Common-Cause Challenge</div></article><article class="card research-card"><div class="eyebrow">05 / Equal-priority review</div><h2>A group is not a shortcut.</h2><p>Phase 9.2 preserves complete representation-relative equivalence classes. Ten equal-priority hypotheses require ten inspections. Historical ranking and routing failures remain historical failures; grouping does not establish analyst productivity.</p><div class="source-cite">Sources: Phase 9.2 Ambiguity Equivalence Contract and Review Burden Report</div></article><article class="card research-card"><div class="eyebrow">06 / Operating envelope</div><h2>Know when interpretation stops.</h2><p>Four inherited expected-out-of-support disagreements remain in the broader development benchmark. Only 327 of 477 original development parents were matched in reviewable queues. Source fidelity does not certify unique-parent correctness. No fresh real-population or human-utility validation is available.</p><div class="source-cite">Source: Phase 9.2 Ambiguity Equivalence Report · full original denominators retained</div></article></div><div class="ambiguity-note"><strong>The current demonstration is intentionally restricted.</strong><p>Frozen synthetic development outputs. Fixed May 2022 observation window. Read-only investigation support. No production or causal-adjudication capability is claimed.</p></div></section>`;}
function lineage(){pageTitle('Evidence lineage');setActive('lineage');main.innerHTML=`<section class="animate-in"><div class="page-heading"><div><div class="eyebrow">Source integrity & reproducibility</div><h1>Frozen at the source.<br><span class="gradient-text">Transparent in the view.</span></h1><p>Five complete run envelopes. All source fields preserved. Presentation mappings are separate from scientific outputs.</p></div>${badge('OFFLINE / NO CONNECTORS')}</div><div class="neutral-note">Architecture: frozen PHANTOM artifacts → read-only presentation adapter → investigation interface. No detector runs, training, evidence edits or review-state transitions are performed here.</div><div class="lineage-list">${INDEX.sources.map(s=>`<section class="card lineage-card"><div class="inline-heading"><h2>${e(s.alias)} · ${e(s.label)}</h2>${badge(s.run_outcome)}</div><p>${e(s.description)}</p><div class="source-strip">${Object.entries(s.queue_counts).map(([t,n])=>badge('Tier '+t+' · '+n,'tier-'+t)).join('')}</div><dl class="source-metadata"><dt>Frozen source</dt><dd>${e(s.source_path)}</dd><dt>Run ID · global class scope</dt><dd class="mono">${e(s.run_id)}</dd></dl><div class="lineage-hash">SHA-256 · ${e(s.sha256)}</div><p>01 May 2022 00:00:00 UTC ≤ observation &lt; 29 May 2022 00:00:00 UTC. Original packets contain exact intervals and source references.</p><div class="button-row"><button class="row-open" data-action="source-queue" data-source="${s.alias}">Inspect fixture ↗</button><a class="artifact-link" href="data/${s.alias}.json" download="PHANTOM_${s.alias}_Frozen_Run.json">Download original run ↓</a></div></section>`).join('')}</div><section class="card card-pad section-spacer"><h2>Approved action presentation mapping</h2><p class="scope-note">The Phase 10 request specifies a closed action vocabulary different from the frozen source. The user approved this mapping. Every source recommended_action remains unchanged in the packet and visible beside its display label.</p><div class="table-wrap"><table class="numeric-table"><caption class="sr-only">Source action to approved presentation label</caption><thead><tr><th scope="col">Frozen source action</th><th scope="col">Phase 10 display label</th></tr></thead><tbody>${Object.entries(A.ACTIONS).map(([k,v])=>`<tr><td>${e(k)}</td><td>${e(v)}</td></tr>`).join('')}</tbody></table></div></section><div class="neutral-note">The original source references are retained; upstream event arrays, protected evaluator labels, consumed validation populations and sealed-final material are excluded from this portable package. Source digests establish artifact identity, not independent validation of every scientific claim.</div></section>`;}
function showModal(title,html){lastFocus=document.activeElement;document.getElementById('modal-title').textContent=title;document.getElementById('modal-content').innerHTML=html;const d=document.getElementById('modal');if(!d.open)d.showModal();}
function download(name,obj){const blob=new Blob([JSON.stringify(obj,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function help(){showModal('Your investigation workspace',`<p>Start with <strong>Observatory</strong> for scope and counts. Open <strong>Investigation queue</strong> to review complete classes. Queue order is administrative; every cause remains unresolved.</p><h3>Complete ties</h3><p>Filters keep every member of a matching equivalence class. Open the complete class, then choose any member. No member is preselected or given a causal rank.</p><h3>Graph & timeline</h3><p>Circles are users and diamonds are tracks. Drag to pan; use + / − or Reset. Focus the graph and use arrow keys to pan. Use the labeled node selector to inspect any user or target with the keyboard. Solid lines show observed temporal relationships; dashed lines show catalog or cross-fragment context. Layout has no scientific meaning.</p><p>Timeline playback is retrospective. Use the labeled slider with the arrow keys or choose Play observations. Full interval restores aggregate evidence. Playback ends at the last recorded window.</p><h3>Evidence & uncertainty</h3><p>Every campaign has all 17 evidence sections, S1–S8 checks, six alternatives and ten missing-provenance questions. Expand a section for exact source content. Full source packet and complete-run downloads preserve the frozen outputs.</p><h3>NEXUS presentation modes</h3><p>PHANTOM is a NEXUS Research Initiative project. Academic view uses a light, reduced-glow presentation. Export academic brief downloads a self-contained research report with a monochrome lockup and the full immutable source packet. Browser printing includes open appendices. Original JSON downloads remain unchanged.</p><h3>Read-only scope</h3><p>There are no scientific edits, support overrides or review transitions. Tier D retains raw diagnostics with interpretation withheld. Pause motion controls decoration; operating-system reduced-motion preferences are respected.</p><h3>Availability</h3><p>AVAILABLE means sourced content exists. NOT AVAILABLE IN CURRENT DATA means no value is supplied. REVIEW REQUIRED is an unfinished review. NOT APPLICABLE means the field has no defined value under this contract.</p>`);}
document.querySelector('.skip-link').addEventListener('click',ev=>{ev.preventDefault();main.focus();main.scrollIntoView({block:'start'});});
document.addEventListener('click',ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='queue')go('queue');if(a==='tier'){filters={tier:el.dataset.tier};go('queue');}
 if(a==='source-queue'){filters={source:el.dataset.source};go('queue');}
 if(a==='reset-filters'){filters={};queue();}
 if(a==='case')go('case/'+el.dataset.source+'/'+el.dataset.id+'/structure');
 if(a==='group')go('group/'+el.dataset.source+'/'+el.dataset.id);
 if(a==='tab')go('case/'+current.source+'/'+current.candidate.campaign_id+'/'+el.dataset.tab);
 if(a==='academic-report')NexusBrand.exportReport(current.candidate,A.action(current.candidate));
 if(a==='help')help();if(a==='retry')route();
 if(a==='close-dialog')document.getElementById('modal').close();
 if(a==='packet')showModal('Immutable source packet · '+short(current.candidate.campaign_id),`<p>Exact Phase 9.2 candidate fields, including original action labels. No presentation mapping changes this source object.</p><pre class="json-box full" tabindex="0">${e(JSON.stringify(current.candidate,null,2))}</pre>`);
 if(a==='workflow')showModal('Immutable review state & history',`<p>Reading this view does not record a transition. No controls change the source workflow. All retained structural findings would still remain causally unresolved.</p><pre class="json-box">${e(JSON.stringify(current.candidate.workflow,null,2))}</pre><h3>Frozen allowed transitions</h3><p>STRUCTURAL_FINDING → CAUSAL_AMBIGUITY or OUT_OF_SUPPORT.<br>CAUSAL_AMBIGUITY → EXTERNAL_PROVENANCE_REQUIRED, STRUCTURAL_FINDING_RETAINED or OUT_OF_SUPPORT.<br>EXTERNAL_PROVENANCE_REQUIRED → STRUCTURAL_FINDING_RETAINED or OUT_OF_SUPPORT.<br>STRUCTURAL_FINDING_RETAINED and OUT_OF_SUPPORT are terminal. All real transitions would require sourced reviewer records under a separately versioned workflow.</p>`);
 if(a==='export-group'){const g=current.group;download('PHANTOM_'+current.source+'_Complete_Class_'+g.equivalence_set_id.slice(5,13)+'.json',{schema_version:'PHANTOM_Phase10_Complete_Class_Export_v1',run_id:current.run.run_id,source:INDEX.sources.find(s=>s.alias===current.source),presentation_order_semantic:false,ambiguity_equivalence_set:g,candidates:g.member_candidate_ids.map(id=>current.run.candidates.find(c=>c.campaign_id===id))});announce('Complete class exported with every member and all source limitations.');}
});
document.getElementById('modal').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
let paused=matchMedia('(prefers-reduced-motion: reduce)').matches;try{paused=localStorage.getItem('phantom-motion')==='paused'||paused;}catch{}
function motion(){document.body.classList.toggle('no-motion',paused);const b=document.getElementById('motion-toggle');b.textContent=paused?'Resume motion':'Pause motion';b.setAttribute('aria-pressed',String(paused));}
motion();document.getElementById('motion-toggle').onclick=()=>{paused=!paused;motion();try{localStorage.setItem('phantom-motion',paused?'paused':'active');}catch{}};
async function route(){const token=++routeSerial;clearInterval(playTimer);playTimer=null;graph?.destroy();graph=null;current=null;const parts=location.hash.replace(/^#/,'').split('/'),page=parts[0]||'overview';if(['case','group','network'].includes(page))main.innerHTML='<div class="loading-state" role="status">Opening immutable evidence…</div>';try{
 if(page==='overview')await overview(token);else if(page==='queue')queue();else if(page==='group')await groupPage(parts[1],parts[2],token);else if(page==='case')await detail(parts[1],parts[2],parts[3],token);else if(page==='network')await networkPage(parts[1]||'R-01',parts[2]||'',token);else if(page==='research')research();else if(page==='lineage')lineage();else throw Error('Unknown workspace view.');
 if(token!==routeSerial)return;NexusBrand.apply();window.__phantomState.route=location.hash||'#overview';main.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});
 }catch(err){if(token!==routeSerial)return;main.innerHTML=`<section class="empty-state" role="alert"><h1>Evidence view unavailable</h1><p>${e(err.message)}</p><p>No missing data have been substituted. Return to the overview or retry the frozen packet.</p><button data-action="retry">Retry</button><a class="artifact-link" href="#overview">Overview</a></section>`;console.error(err);}}
window.addEventListener('hashchange',route);
const start=performance.now();route().then(()=>requestAnimationFrame(()=>{window.__phantomMetrics.initial_load=performance.now()-start;window.__phantomReady=true;}));
})();
